def test_si_se_agota_toda_la_nube_queda_el_local():
    for q in cuotas.ORDEN:
        if q != "local":
            cuotas.dormir(q, "429 quota")
    assert cuotas.turno() == "local", "con toda la nube agotada debe quedar LM Studio"

